import os,re,collections
root='AlgebraicJacobian.lean'
def mod2path(m):
    return m.replace('.','/')+'.lean'
def imports(p):
    out=[]
    try:
        for line in open(p, encoding='utf-8', errors='replace'):
            s=line.strip()
            if s.startswith('import '):
                out.append(s.split()[1])
            elif s and not s.startswith('--') and not s.startswith('/-') and not s.startswith('import'):
                break
    except FileNotFoundError:
        pass
    return out
seen=set(); stack=[m for m in imports(root) if m.startswith('AlgebraicJacobian')]
while stack:
    m=stack.pop()
    if m in seen: continue
    seen.add(m)
    for n in imports(mod2path(m)):
        if n.startswith('AlgebraicJacobian') and n not in seen: stack.append(n)
allf=set()
for d,_,fs in os.walk('AlgebraicJacobian'):
    for f in fs:
        if f.endswith('.lean'):
            allf.add(os.path.join(d,f)[:-5].replace('/','.'))
unreach=sorted(allf-seen)
print('total files', len(allf), 'reachable', len(seen & allf), 'unreachable', len(unreach))
for u in unreach: print('  ', u)
EOF
